document.addEventListener("DOMContentLoaded",function(){document.getElementById("form-sorteador").addEventListener("submit",function(e){e.preventDefault();var e=document.querySelector('input[name="dado"]:checked');e?(e=parseInt(e.value),e=Math.floor(Math.random()*e)+1,document.getElementById("resultado-valor").innerText=e,document.querySelector(".resultado").style.display="block",document.querySelector('button[type="submit"]').blur()):alert("Escolha um dado para rolar!")})});